__NUXT_JSONP__("/desarrollo-sostenible/eventos/el_componente_de_genero_es_indispensable_para_la_accion_climatica", (function(a,b,c,d,e,f,g,h,i){return {data:[{post:{slug:"el_componente_de_genero_es_indispensable_para_la_accion_climatica",title:"El componente de género es indispensable para la acción climática",date:"2024-04-02T22:19:39.345Z",img:"https:\u002F\u002Fucarecdn.com\u002F57d07cf9-94a2-4be2-ab48-a80ff6a9b3c6\u002F-\u002Fcrop\u002F2048x822\u002F0,359\u002F-\u002Fpreview\u002F","img-alt":"Equidad de género e inclusión social en la acción climática",autor:"Ethos",category:"desarrollo-sostenible",extracto:"Al participar en una mesa redonda organizada por la Comunidad Climática Mexicana, la investigadora de Ethos Berenice Valencia resaltó que faltan estadísticas locales sobre cómo enfrentan las mujeres el cambio climático a nivel local, por lo que es necesario realizar un diagnóstico de este tipo al inicio de este tipo de proyectos.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"En el actual contexto, es fundamental incluir el componente de género en proyectos de acción climática porque de no hacerlo, corremos el riesgo de que las desigualdades que ya existen entre hombres y mujeres se mantengan, sino que incluso se incrementen, expresó la investigadora de Ethos, Berenice Valencia, en la mesa redonda "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.comunidadclimaticamexicana.mx\u002Findex.php\u002F2024\u002F03\u002F12\u002Fequidad-genero\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"‘Equidad de género e inclusión social en la acción climática'"}]},{type:a,value:", convocada por la "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.comunidadclimaticamexicana.mx\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Comunidad Climática Mexicana"}]},{type:a,value:"."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Asimismo, destacó la necesidad de realizar diagnósticos sobre cómo enfrentan las mujeres el cambio climático y también efectos específicos como sequías o aumento de temperatura. Lo ideal es que sea al principio del proyecto, porque hacen falta ese tipo de datos; sin embargo, pueden hacerse aunque ya esté avanzado. "}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Sabemos que la crisis climática impacta de manera diferenciada a las mujeres, pero nos faltan estadísticas locales, es decir, usamos muchas estadísticas internacionales para informarnos del tema, pero si pudiéramos tener diagnósticos a nivel municipal, a nivel comunitario, sería mucho mejor”, indicó."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"También señaló que en México y en Latinoamérica hay muchas mujeres defensoras del territorio, del agua, de la calidad del aire, y sus actividades tienen potencial para generar alianzas con gobiernos y organizaciones de la sociedad civil que les permitan incrementar el impacto de lo que ellas ya están haciendo. En este sentido, se debe aprovechar la organización comunitaria y ver cómo vincularnos con ellos de manera justa y equitativa."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Y compartió que desde Ethos nos hemos enfocado en temas climáticos, en fortalecer la resiliencia de las comunidades, y desde nuestra experiencia, es importante trabajar considerando el contexto de cada comunidad y realizar consultas participativas si se quiere incluir a las mujeres, preguntarles qué necesitan para ser parte de los proyectos. "}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Esto tiene que ver con la perspectiva de la interseccionalidad, por ejemplo, reconociendo el trabajo de cuidados y contemplarlo en los proyectos podemos aumentar la participación de las mujeres”, dijo."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Respecto al tema de indicadores, comentó que los cuantitativos son clave, pero es necesario mezclarlos con los cualitativos. Al respecto, resaltó la importancia de ir más allá e invitó a explorar y usar, por ejemplo, métodos etnográficos, de participación observante, que permiten a las personas investigadoras comprender mejor el impacto que tienen los proyectos en las comunidades."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En esta mesa redonda también participaron Mariana Carolina Guerrero Rivera, asesora de la Alianza Energética México-Alemania y Cooperación Triangular México, Cuba y Alemania, GIZ; Dulce M Guevara, especialista en Políticas Públicas en Energía y Género en GGGI; Itzá Castañeda, directora de Equidad Social en WRI México, y como moderadora, Patricia Guzmán, Gerente de Asuntos Públicos, Vinculación y Capacitación en WRI México."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fel_componente_de_genero_es_indispensable_para_la_accion_climatica",extension:".md",createdAt:"2024-10-02T22:32:44.078Z",updatedAt:"2024-10-02T22:32:44.079Z"}}],fetch:{},mutations:[]}}("text","element","p","\n","a","nofollow","noopener","noreferrer","_blank")));